import{_ as l,l as i,o as e,c as s,v as r,p as n,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"堆 UAF","description":"","frontmatter":{"title":"堆 UAF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-uaf.md","filePath":"cs/heap-uaf.md","lastUpdated":1789023840000}'),c={name:"cs/heap-uaf.md"};function E(u,a,_,f,A,m){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="堆-uaf" tabindex="-1">堆 UAF <a class="header-anchor" href="#堆-uaf" aria-label="Permalink to &quot;堆 UAF&quot;">​</a></h1><div class="epigraph"><p>释放后指针仍被解引用，对象槽可能已租给别人。读则泄，写则改别人的对象——包括函数指针。生命周期错误与越界写是两条路，都能到达同一类控制数据。</p><footer>—— 据 Szekeres et al., SoK: Eternal War in Memory, Oakland 2013；对照 CWE-416</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/jop-cop">JOP</a>要函数指针可写。缺口是<strong>堆生命周期</strong>：UAF。本课讲悬挂指针与分配器复用，不给利用堆布局的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>free</code> 后未置空，后续使用碰到新对象。类型若不同，就是混淆的入口。缺口是所有权，不是再讲栈帧。语言与 GC、或 borrow checker，从根上删这类。</p><h3 id="双重释放" tabindex="-1">双重释放 <a class="header-anchor" href="#双重释放" aria-label="Permalink to &quot;双重释放&quot;">​</a></h3><p>重复 <code>free</code> 破坏分配器元数据，下一课专门收。UAF 是「用」；double-free 是「还两次」。</p><p><span class="marginnote">Szekeres SoK。ASan 后课检测。本课禁止构造 UAF 利用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：分配→释放→槽复用→悬挂指针。防御：置空、隔离释放、延迟复用、内存安全语言。对照 canary：帮不上堆对象内部。</p>',12)),(e(),n(p,null,{default:t(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E5%88%86%E9%85%8D%22%5D%20--%3E%20FREE%5B%22%E9%87%8A%E6%94%BE%22%5D%0A%20%20FREE%20--%3E%20REUSE%5B%22%E6%A7%BD%E5%A4%8D%E7%94%A8%22%5D%0A%20%20DANG%5B%22%E6%82%AC%E6%8C%82%E6%8C%87%E9%92%88%22%5D%20--%3E%20REUSE%0A%20%20DANG%20--%3E%20BUG%5B%22%E8%AF%BB%E6%B3%84%E6%88%96%E5%86%99%E4%B8%B2%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>堆把时间轴引进空间安全。下一课分配器自身的元数据：chunk 头被改时，分配器成为原语。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无堆风水。分配器攻击下一课仍只讲机制与加固。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制数据也可住在堆对象里。</li><li>UAF：释放后用，槽可能已是别人。</li><li>所有权与安全语言是根治；检测器后课。</li><li>下一课分配器元数据。</li><li>出处：Szekeres et al., Oakland 2013；CWE-416。</li></ul>',8))])}const B=l(c,[["render",E]]);export{k as __pageData,B as default};
